// 治理中央命令、报价和回执只转换显式字段；资源与任务真实性由具名业务入口核验。
#include "governance_integration.hpp"
#include "resident/checkpoint/codec_visitor.hpp"
namespace hanmo::resident {
namespace {
using V=BoundaryValue;
// 共同authority四字段沿原组织合同，不让玩家提交grant、钱粮或完工事实。
V authority(const ActingAuthority& a){return boundary::obj({{"organization_id",V{a.organization_id}},{"office_id",V{a.office_id}},{"authority_epoch",V{a.authority_epoch}},{"actor_id",V{a.actor_id}}});}
ActingAuthority authority(const V& v){boundary::fields(v,{"organization_id","office_id","authority_epoch","actor_id"},{},"authority");return {boundary::get_string(v,"organization_id","authority"),boundary::get_string(v,"office_id","authority"),boundary::get_int(v,"authority_epoch","authority"),boundary::get_string(v,"actor_id","authority")};}
V identity(const WorldIdentity& i){StableId hex;const char* digits="0123456789abcdef";for(auto b:i.world_id){hex+=digits[b>>4];hex+=digits[b&15];}return boundary::obj({{"world_id",V{hex}},{"execution_epoch",V{i.execution_epoch}},{"revision",V{i.revision}},{"tick",V{i.tick}}});}
WorldIdentity identity(const V& v){boundary::fields(v,{"world_id","execution_epoch","revision","tick"},{},"identity");WorldIdentity out;const auto hex=boundary::get_string(v,"world_id","identity");if(hex.size()!=32)boundary::fail("InvalidGovernanceWorldIdentity","identity/world_id");auto nibble=[](char c){return c>='0'&&c<='9'?c-'0':c>='a'&&c<='f'?c-'a'+10:-1;};for(std::size_t n=0;n<out.world_id.size();++n){int a=nibble(hex[n*2]),b=nibble(hex[n*2+1]);if(a<0||b<0)boundary::fail("InvalidGovernanceWorldIdentity","identity/world_id");out.world_id[n]=static_cast<std::uint8_t>(a*16+b);}out.execution_epoch=boundary::get_int(v,"execution_epoch","identity");out.revision=boundary::get_int(v,"revision","identity");out.tick=boundary::get_int(v,"tick","identity");if(out.execution_epoch<0||out.revision<0||out.tick<0)boundary::fail("InvalidGovernanceWorldIdentity","identity");return out;}
}
BoundaryValue encode_governance_command(const GovernanceCommand& command){return std::visit([](const auto& c)->V{using T=std::decay_t<decltype(c)>;if constexpr(std::is_same_v<T,PoliticalGovernanceCommissionCommand>)return boundary::obj({{"authority",authority(c.authority)},{"executor_actor_id",V{c.executor_actor_id}},{"jurisdiction_id",V{c.jurisdiction_id}},{"policy_id",V{c.policy_id}},{"public_inventory_id",V{c.public_inventory_id}},{"expected_jurisdiction_revision",V{c.expected_jurisdiction_revision}}});else if constexpr(std::is_same_v<T,GovernanceAcceptCommand>)return boundary::obj({{"authority_fact_id",V{c.authority_fact_id}},{"expected_world_revision",V{c.expected_world_revision}}});else return boundary::obj({{"task_id",V{c.task_id}},{"expected_world_revision",V{c.expected_world_revision}}});},command);}
Outcome<GovernanceCommand> decode_governance_command(const StableId& kind,const BoundaryValue& v){try{using namespace boundary;
    if(kind=="political_commission_governance"){fields(v,{"authority","executor_actor_id","jurisdiction_id","policy_id","public_inventory_id","expected_jurisdiction_revision"},{},"params");PoliticalGovernanceCommissionCommand c;c.authority=authority(field(v,"authority","params"));c.executor_actor_id=get_string(v,"executor_actor_id","params");c.jurisdiction_id=get_string(v,"jurisdiction_id","params");c.policy_id=get_string(v,"policy_id","params");c.public_inventory_id=get_string(v,"public_inventory_id","params");c.expected_jurisdiction_revision=get_int(v,"expected_jurisdiction_revision","params");return {true,c,{}};}
    if(kind=="governance_accept"){fields(v,{"authority_fact_id","expected_world_revision"},{},"params");return {true,GovernanceAcceptCommand{get_string(v,"authority_fact_id","params"),get_int(v,"expected_world_revision","params")},{}};}
    if(kind=="governance_cancel"){fields(v,{"task_id","expected_world_revision"},{},"params");return {true,GovernanceCancelCommand{get_string(v,"task_id","params"),get_int(v,"expected_world_revision","params")},{}};}
    return {false,{},common_failure("UnsupportedGovernanceCommand",kind,ErrorKind::unsupported_capability).error};
}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
BoundaryValue encode_governance_quote(const GovernanceQuote& q){return boundary::obj({{"identity",identity(q.identity)},{"actor_id",V{q.actor_id}},{"duration",V{q.duration}},{"command_kind",V{governance_command_kind(q.command)}},{"command",encode_governance_command(q.command)}});}
Outcome<GovernanceQuote> decode_governance_quote(const BoundaryValue& v){try{using namespace boundary;fields(v,{"identity","actor_id","duration","command_kind","command"},{},"quote");GovernanceQuote q;q.identity=identity(field(v,"identity","quote"));q.actor_id=get_string(v,"actor_id","quote");q.duration=get_int(v,"duration","quote");if(q.actor_id.empty()||q.duration!=0)fail("InvalidGovernanceQuote","quote");auto command=decode_governance_command(get_string(v,"command_kind","quote"),field(v,"command","quote"));if(!command.ok)return {false,{},command.error};q.command=std::move(command.value);return {true,std::move(q),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
BoundaryValue encode_governance_effects(const GovernanceEffects& e){return boundary::obj({{"authority_fact_id",V{e.authority_fact_id}},{"task_id",V{e.task_id}},{"action_id",V{e.action_id}},{"result_fact_id",V{e.result_fact_id}},{"relief_fact_id",V{e.relief_fact_id}}});}
Outcome<GovernanceEffects> decode_governance_effects(const BoundaryValue& v){try{using namespace boundary;fields(v,{"authority_fact_id","task_id","action_id","result_fact_id","relief_fact_id"},{},"effects");return {true,{get_string(v,"authority_fact_id","effects"),get_string(v,"task_id","effects"),get_string(v,"action_id","effects"),get_string(v,"result_fact_id","effects"),get_string(v,"relief_fact_id","effects")},{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status visit_governance_effects(CodecVisitor& c,GovernanceEffects& e){c.field("authority_fact_id",e.authority_fact_id);c.field("task_id",e.task_id);c.field("action_id",e.action_id);c.field("result_fact_id",e.result_fact_id);c.field("relief_fact_id",e.relief_fact_id);return c.status();}
}
